:root {
  /* Colors */
  --color-primary: #141414;
  --color-bg: #FFFFFF;
  --color-surface: #F5F5F5;
  --color-surface-hover: #E5E5E5;
  --color-accent: #2563EB;
  --color-accent-hover: #1D4ED8;
  --color-text: #141414;
  --color-text-muted: #64748B;
  --color-border: #E2E8F0;

  /* Typography */
  --font-family: 'Inter', sans-serif;
  --font-size-base: 16px;

  /* Spacing */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-8: 64px;
  --space-12: 96px;
  --space-16: 128px;

  /* Radius & Shadows */
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-pill: 9999px;

  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.05), 0 4px 6px -2px rgba(0, 0, 0, 0.025);

  /* Transitions */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 400ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  line-height: 1.5;
  color: var(--color-text);
  background-color: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: var(--color-text);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--color-accent);
}

img, svg {
  display: block;
  max-width: 100%;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* Layout */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--space-4);
}

section {
  padding: var(--space-12) 0;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-3) var(--space-6);
  font-weight: 500;
  border-radius: var(--radius-pill);
  transition: all var(--transition-fast);
  text-align: center;
}

.btn-sm {
  padding: var(--space-2) var(--space-4);
  font-size: 0.875rem;
}

.btn-primary {
  background-color: var(--color-primary);
  color: #FFFFFF;
}

.btn-primary:hover {
  background-color: #000000;
  color: #FFFFFF;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background-color: var(--color-surface);
  color: var(--color-text);
}

.btn-secondary:hover {
  background-color: var(--color-surface-hover);
  color: var(--color-text);
}

/* Announcement Bar */
.announcement-bar {
  background-color: var(--color-primary);
  color: #FFFFFF;
  text-align: center;
  padding: var(--space-2) var(--space-4);
  font-size: 0.875rem;
  font-weight: 500;
}

.announcement-bar a {
  color: #FFFFFF;
  text-decoration: underline;
  text-decoration-color: rgba(255,255,255,0.4);
  margin-left: var(--space-2);
}

.announcement-bar a:hover {
  text-decoration-color: #FFFFFF;
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
  padding: var(--space-3) 0;
}

.header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-weight: 700;
  font-size: 1.125rem;
  letter-spacing: -0.01em;
}

.desktop-nav {
  display: none;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.login-link {
  font-weight: 500;
  font-size: 0.875rem;
}

@media (min-width: 768px) {
  .desktop-nav {
    display: flex;
    gap: var(--space-6);
    font-weight: 500;
    font-size: 0.875rem;
  }
}

/* Hero Section */
.hero {
  text-align: center;
  padding-top: var(--space-16);
  padding-bottom: var(--space-16);
}

.hero-title {
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.1;
  margin-bottom: var(--space-4);
}

.hero-subtitle {
  font-size: clamp(1.125rem, 2vw, 1.25rem);
  color: var(--color-text-muted);
  max-width: 600px;
  margin: 0 auto var(--space-6);
}

.hero-actions {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  justify-content: center;
  align-items: center;
  margin-bottom: var(--space-12);
}

@media (min-width: 480px) {
  .hero-actions {
    flex-direction: row;
  }
}

.hero-visual {
  position: relative;
  max-width: 900px;
  margin: 0 auto;
  height: 400px;
  perspective: 1000px;
}

.mockup-grid {
  display: flex;
  justify-content: center;
  gap: var(--space-4);
  position: relative;
  transform-style: preserve-3d;
}

.mockup-card {
  width: 240px;
  height: 500px;
  background-color: var(--color-surface);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--color-border);
  animation: floatUp 1s ease-out forwards;
  animation-delay: var(--delay);
  opacity: 0;
  transform: translateY(40px);
}

.mockup-card:nth-child(even) {
  transform: translateY(80px);
}

@keyframes floatUp {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Social Proof */
.social-proof {
  padding: var(--space-8) 0;
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
  background-color: #FAFAFA;
  overflow: hidden;
}

.section-label {
  text-align: center;
  color: var(--color-text-muted);
  font-size: 0.875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-6);
}

.logo-marquee {
  display: flex;
  width: 200%;
}

.logo-track {
  display: flex;
  justify-content: space-around;
  width: 50%;
  animation: marquee 30s linear infinite;
}

.brand-logo {
  font-weight: 700;
  font-size: 1.5rem;
  color: #A0AEC0;
  letter-spacing: -0.02em;
}

@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-100%); }
}

/* Stats */
.stats {
  padding: var(--space-16) 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-8);
  text-align: center;
}

@media (min-width: 768px) {
  .stats-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.stat-number {
  font-size: clamp(3rem, 5vw, 4rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-accent);
  margin-bottom: var(--space-2);
  line-height: 1;
}

.stat-label {
  font-size: 1.125rem;
  color: var(--color-text-muted);
  font-weight: 500;
}

/* Common Section Header */
.section-header {
  text-align: center;
  margin-bottom: var(--space-12);
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
}

.section-header h2 {
  font-size: clamp(2rem, 4vw, 2.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-4);
  line-height: 1.2;
}

.section-header p {
  font-size: 1.125rem;
  color: var(--color-text-muted);
}

/* Feature: Search */
.feature-search {
  background-color: #FAFAFA;
}

.search-interface {
  background: var(--color-bg);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
}

.search-tabs {
  display: flex;
  gap: var(--space-2);
  border-bottom: 1px solid var(--color-border);
  margin-bottom: var(--space-6);
  overflow-x: auto;
  scrollbar-width: none;
}

.search-tabs::-webkit-scrollbar {
  display: none;
}

.tab-btn {
  padding: var(--space-3) var(--space-4);
  font-weight: 500;
  color: var(--color-text-muted);
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--color-text);
}

.tab-btn.active {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
}

.filter-pills-container {
  overflow-x: auto;
  margin-bottom: var(--space-6);
  padding-bottom: var(--space-2);
  scrollbar-width: none;
}
.filter-pills-container::-webkit-scrollbar {
  display: none;
}

.filter-pills {
  display: flex;
  gap: var(--space-2);
}

.pill {
  padding: var(--space-2) var(--space-4);
  background-color: var(--color-surface);
  border: 1px solid transparent;
  border-radius: var(--radius-pill);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.pill:hover {
  background-color: var(--color-surface-hover);
  color: var(--color-text);
}

.pill.active {
  background-color: var(--color-primary);
  color: #FFFFFF;
}

.search-results {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-4);
}

.result-card {
  aspect-ratio: 9/19;
  background-color: var(--color-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  transition: transform var(--transition-fast);
}

.result-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

/* Feature: Flows */
.flows-interface {
  max-width: 900px;
  margin: 0 auto;
}

.toggle-switch {
  display: flex;
  background-color: var(--color-surface);
  padding: var(--space-1);
  border-radius: var(--radius-pill);
  width: fit-content;
  margin: 0 auto var(--space-8);
}

.toggle-btn {
  padding: var(--space-2) var(--space-6);
  border-radius: var(--radius-pill);
  font-weight: 500;
  color: var(--color-text-muted);
  transition: all var(--transition-fast);
}

.toggle-btn.active {
  background-color: var(--color-bg);
  color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.flow-viewer {
  background-color: var(--color-surface);
  border-radius: var(--radius-xl);
  aspect-ratio: 16/9;
  overflow: hidden;
  position: relative;
  border: 1px solid var(--color-border);
}

.flow-content {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition-base);
}

.flow-content.active {
  opacity: 1;
  pointer-events: auto;
}

.fake-video-player {
  width: 100%;
  height: 100%;
  background: linear-gradient(45deg, #E2E8F0, #CBD5E1);
  display: flex;
  align-items: center;
  justify-content: center;
}

.play-btn {
  width: 64px;
  height: 64px;
  background-color: rgba(0,0,0,0.5);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(4px);
  cursor: pointer;
  transition: transform var(--transition-fast);
}

.play-btn:hover {
  transform: scale(1.1);
}

.fake-prototype {
  width: 100%;
  height: 100%;
  background-color: #F8FAFC;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.hotspot {
  width: 48px;
  height: 48px;
  background-color: rgba(37, 99, 235, 0.2);
  border: 2px solid var(--color-accent);
  border-radius: 50%;
  position: absolute;
  animation: pulse 2s infinite;
  cursor: pointer;
}

@keyframes pulse {
  0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(37, 99, 235, 0.4); }
  70% { transform: scale(1); box-shadow: 0 0 0 15px rgba(37, 99, 235, 0); }
  100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(37, 99, 235, 0); }
}

/* Tools */
.feature-tools {
  background-color: var(--color-primary);
  color: #FFFFFF;
}

.feature-tools .section-header h2 {
  color: #FFFFFF;
}

.tools-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-6);
}

@media (min-width: 768px) {
  .tools-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.tool-card {
  background-color: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  padding: var(--space-8) var(--space-6);
  border-radius: var(--radius-xl);
  transition: transform var(--transition-fast);
}

.tool-card:hover {
  transform: translateY(-4px);
  background-color: rgba(255,255,255,0.08);
}

.tool-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  margin-bottom: var(--space-4);
  background-color: rgba(255,255,255,0.1);
}

.tool-card h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-2);
  font-weight: 600;
}

.tool-card p {
  color: rgba(255,255,255,0.7);
  line-height: 1.6;
}

/* Testimonials */
.testimonials {
  overflow: hidden;
}

.testimonial-marquee-container {
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
  padding: 0 var(--space-4);
}

.testimonial-track {
  display: flex;
  gap: var(--space-6);
  width: max-content;
}

.track-ltr {
  animation: marquee-ltr 40s linear infinite;
}

.track-rtl {
  animation: marquee-rtl 40s linear infinite;
  transform: translateX(-50%);
}

@keyframes marquee-ltr {
  0% { transform: translateX(0); }
  100% { transform: translateX(calc(-50% - 12px)); }
}

@keyframes marquee-rtl {
  0% { transform: translateX(calc(-50% - 12px)); }
  100% { transform: translateX(0); }
}

.testimonial-card {
  width: 400px;
  padding: var(--space-6);
  background-color: var(--color-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.quote {
  font-size: 1.125rem;
  line-height: 1.6;
  color: var(--color-text);
  margin-bottom: var(--space-6);
}

.author {
  font-size: 0.875rem;
  color: var(--color-text-muted);
}

.author strong {
  color: var(--color-text);
  font-weight: 600;
}

/* Final CTA */
.final-cta {
  text-align: center;
  overflow: hidden;
  padding-bottom: 0;
}

.final-cta h2 {
  font-size: clamp(2.5rem, 4vw, 3.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-4);
}

.final-cta p {
  font-size: 1.125rem;
  color: var(--color-text-muted);
  max-width: 600px;
  margin: 0 auto var(--space-8);
}

.app-icon-marquee {
  margin-top: var(--space-16);
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  background: linear-gradient(180deg, transparent, var(--color-surface) 100%);
  padding-top: var(--space-8);
  padding-bottom: var(--space-8);
}

.icon-track {
  display: flex;
  gap: var(--space-4);
  width: max-content;
}

.app-icon {
  width: 80px;
  height: 80px;
  background-color: var(--color-bg);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--color-text-muted);
  border: 1px solid var(--color-border);
}

/* Footer */
.site-footer {
  background-color: var(--color-surface);
  padding: var(--space-12) 0 var(--space-6);
  border-top: 1px solid var(--color-border);
}

.footer-top {
  display: flex;
  flex-direction: column;
  gap: var(--space-12);
  margin-bottom: var(--space-12);
}

@media (min-width: 768px) {
  .footer-top {
    flex-direction: row;
    justify-content: space-between;
  }
}

.footer-brand .logo {
  margin-bottom: var(--space-4);
}

.footer-brand .tagline {
  color: var(--color-text-muted);
  max-width: 300px;
}

.footer-links {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-8);
}

@media (min-width: 600px) {
  .footer-links {
    grid-template-columns: repeat(3, 1fr);
  }
}

.link-col h4 {
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-4);
  color: var(--color-text);
}

.link-col a {
  display: block;
  color: var(--color-text-muted);
  margin-bottom: var(--space-3);
  font-size: 0.875rem;
}

.footer-bottom {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  border-top: 1px solid var(--color-border);
  padding-top: var(--space-6);
  color: var(--color-text-muted);
  font-size: 0.875rem;
}

@media (min-width: 600px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.legal-links {
  display: flex;
  gap: var(--space-4);
}

document.addEventListener('DOMContentLoaded', () => {

  // --- 1. Stats Counter Animation ---
  const statsSection = document.getElementById('stats-section');
  const statNumbers = document.querySelectorAll('.stat-number');
  let animated = false;

  const formatNumber = (num) => {
    return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  };

  const animateNumbers = () => {
    statNumbers.forEach(stat => {
      const target = parseInt(stat.getAttribute('data-target'), 10);
      const duration = 2000; // ms
      const frameRate = 1000 / 60; // 60fps
      const totalFrames = Math.round(duration / frameRate);
      let currentFrame = 0;

      const easeOutQuart = (t) => 1 - Math.pow(1 - t, 4);

      const updateCounter = () => {
        currentFrame++;
        const progress = currentFrame / totalFrames;
        const currentNum = Math.round(target * easeOutQuart(progress));

        stat.textContent = formatNumber(currentNum);

        if (currentFrame < totalFrames) {
          requestAnimationFrame(updateCounter);
        } else {
          stat.textContent = formatNumber(target);
        }
      };

      updateCounter();
    });
  };

  const statsObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting && !animated) {
        animateNumbers();
        animated = true;
        statsObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.5 });

  if (statsSection) {
    statsObserver.observe(statsSection);
  }

  // --- 2. Search Tabs Toggle ---
  const tabBtns = document.querySelectorAll('.tab-btn');
  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      // Remove active from all tabs
      tabBtns.forEach(b => b.classList.remove('active'));
      // Add active to clicked tab
      btn.classList.add('active');

      // In a real app, this would also filter the results grid
      const grid = document.getElementById('search-results-grid');
      grid.style.opacity = '0.5';
      setTimeout(() => { grid.style.opacity = '1'; }, 200);
    });
  });

  // --- 3. Search Filters Toggle ---
  const filterPills = document.querySelectorAll('.pill');
  filterPills.forEach(pill => {
    pill.addEventListener('click', () => {
      // Remove active from all pills
      filterPills.forEach(p => p.classList.remove('active'));
      // Add active to clicked pill
      pill.classList.add('active');

      // Simulate loading state
      const grid = document.getElementById('search-results-grid');
      grid.style.opacity = '0.5';
      setTimeout(() => { grid.style.opacity = '1'; }, 200);
    });
  });

  // --- 4. Flows Toggle ---
  const flowToggles = document.querySelectorAll('.toggle-btn');
  const flowContents = document.querySelectorAll('.flow-content');

  flowToggles.forEach(toggle => {
    toggle.addEventListener('click', () => {
      const mode = toggle.getAttribute('data-flow-mode');

      // Update toggle buttons
      flowToggles.forEach(t => t.classList.remove('active'));
      toggle.classList.add('active');

      // Update content view
      flowContents.forEach(content => {
        content.classList.remove('active');
        if (content.classList.contains(`${mode}-mode`)) {
          content.classList.add('active');
        }
      });
    });
  });

});

